    20→// CheckAndNotify performs a version check and notifies the user if a newer version is available.
    21→// This is the main entry point for the version check system.
    22→// The function is silent on all errors to avoid interrupting CLI operations.
    23→func CheckAndNotify(cmd *cobra.Command, currentVersion string) {
    24→	// Skip checks for hidden commands
    25→	if cmd.Hidden {
    26→		return
    27→	}
    28→
    29→	// Skip checks for dev builds
    30→	if currentVersion == "dev" || currentVersion == "" {
    31→		return
    32→	}
    33→
    34→	// Ensure the global config directory exists
    35→	if err := ensureGlobalConfigDir(); err != nil {
    36→		// Silent failure - don't block CLI operations
    37→		return
    38→	}
    39→
    40→	// Load the cache to check when we last fetched
    41→	cache, err := loadCache()
    42→	if err != nil {
    43→		cache = &VersionCache{}
    44→	}
    45→
    46→	// Skip if we checked recently (within 24 hours)
    47→	if time.Since(cache.LastCheckTime) < checkInterval {
    48→		return
    49→	}
    50→
    51→	// Fetch the latest version from GitHub API
    52→	latestVersion, err := fetchLatestVersion()
    53→	if err != nil {
    54→		// Network error or timeout - silently skip
    55→		logging.Debug(context.Background(), "version check: failed to fetch latest version",
    56→			"error", err.Error())
    57→		return
    58→	}
    59→
    60→	// Update cache with new check time
    61→	cache.LastCheckTime = time.Now()
    62→	if err := saveCache(cache); err != nil {
    63→		logging.Debug(context.Background(), "version check: failed to save cache",
    64→			"error", err.Error())
    65→	}
    66→
    67→	// Show notification if outdated
    68→	if isOutdated(currentVersion, latestVersion) {
    69→		printNotification(cmd, currentVersion, latestVersion)
    70→	}
    71→}
