    73→// globalConfigDirPath returns the expanded path to the global config directory (~/.entire).
    74→func globalConfigDirPath() (string, error) {
    75→	home, err := os.UserHomeDir()
    76→	if err != nil {
    77→		return "", fmt.Errorf("getting home directory: %w", err)
    78→	}
