    86→		return err
    87→	}
    88→
    89→	//nolint:gosec // ~/.entire is user home directory, 0o755 is appropriate
    90→	if err := os.MkdirAll(configDir, 0o755); err != nil {
    91→		return fmt.Errorf("creating config directory: %w", err)
    92→	}
    93→
    94→	return nil
    95→}
