    97→// cacheFilePath returns the full path to the version check cache file.
    98→func cacheFilePath() (string, error) {
    99→	configDir, err := globalConfigDirPath()
   100→	if err != nil {
   101→		return "", err
   102→	}
   103→	return filepath.Join(configDir, cacheFileName), nil
   104→}
