   106→// loadCache loads the version check cache from disk.
   107→// Returns an error if the file doesn't exist or is corrupted.
   108→func loadCache() (*VersionCache, error) {
   109→	filePath, err := cacheFilePath()
   110→	if err != nil {
   111→		return nil, err
   112→	}
   113→
   114→	data, err := os.ReadFile(filePath) //nolint:gosec // cacheFilePath is safe
   115→	if err != nil {
   116→		return nil, fmt.Errorf("reading cache file: %w", err)
   117→	}
   118→
   119→	var cache VersionCache
   120→	if err := json.Unmarshal(data, &cache); err != nil {
   121→		return nil, fmt.Errorf("parsing cache: %w", err)
   122→	}
   123→
   124→	return &cache, nil
   125→}
   126→
   127→// saveCache saves the version check cache to disk.
   128→// Uses atomic write semantics (write to temp file, then rename).
   129→func saveCache(cache *VersionCache) error {
   130→	filePath, err := cacheFilePath()
   131→	if err != nil {
   132→		return err
   133→	}
   134→
   135→	// Marshal to JSON
   136→	data, err := json.MarshalIndent(cache, "", "  ")
   137→	if err != nil {
   138→		return fmt.Errorf("marshaling cache: %w", err)
   139→	}
   140→
   141→	// Write to temp file first (atomic write)
   142→	dir := filepath.Dir(filePath)
   143→	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
   144→	if err != nil {
   145→		return fmt.Errorf("creating temp file: %w", err)
   146→	}
   147→	defer os.Remove(tmpFile.Name())
   148→
   149→	if _, err := tmpFile.Write(data); err != nil {
   150→		_ = tmpFile.Close() // cleanup on error path
   151→		return fmt.Errorf("writing cache: %w", err)
   152→	}
   153→
   154→	if err := tmpFile.Close(); err != nil {
   155→		return fmt.Errorf("closing temp file: %w", err)
   156→	}
   157→
   158→	// Rename temp file to final location
   159→	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
   160→		return fmt.Errorf("renaming cache file: %w", err)
   161→	}
   162→
   163→	return nil
   164→}
