   166→// fetchLatestVersion fetches the latest version from the GitHub API.
   167→// Returns a timeout-safe version check using the configured HTTP timeout.
   168→func fetchLatestVersion() (string, error) {
   169→	// Create a context with timeout for the HTTP request
   170→	ctx, cancel := context.WithTimeout(context.Background(), httpTimeout)
   171→	defer cancel()
   172→
   173→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
   174→	if err != nil {
   175→		return "", fmt.Errorf("creating request: %w", err)
   176→	}
   177→
   178→	// Set headers to identify as Entire CLI
   179→	req.Header.Set("Accept", "application/vnd.github+json")
   180→	req.Header.Set("User-Agent", "entire-cli")
   181→
   182→	client := &http.Client{}
   183→	resp, err := client.Do(req)
   184→	if err != nil {
   185→		return "", fmt.Errorf("fetching release info: %w", err)
   186→	}
   187→	defer resp.Body.Close()
   188→
   189→	if resp.StatusCode != http.StatusOK {
   190→		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
   191→	}
   192→
   193→	// Read response body (limit to prevent large reads)
   194→	body, err := io.ReadAll(resp.Body)
   195→	if err != nil {
   196→		return "", fmt.Errorf("reading response: %w", err)
   197→	}
   198→
   199→	// Parse GitHub release response
   200→	version, err := parseGitHubRelease(body)
   201→	if err != nil {
   202→		return "", fmt.Errorf("parsing release: %w", err)
   203→	}
   204→
   205→	return version, nil
   206→}
   207→
   208→// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
   209→// Filters out prerelease versions.
   210→func parseGitHubRelease(body []byte) (string, error) {
   211→	var release GitHubRelease
   212→	if err := json.Unmarshal(body, &release); err != nil {
   213→		return "", fmt.Errorf("parsing JSON: %w", err)
   214→	}
   215→
   216→	// Skip prerelease versions
   217→	if release.Prerelease {
   218→		return "", errors.New("only prerelease versions available")
   219→	}
   220→
   221→	// Ensure we have a tag name
   222→	if release.TagName == "" {
   223→		return "", errors.New("empty tag name")
   224→	}
   225→
   226→	return release.TagName, nil
   227→}
