   229→// isOutdated compares current and latest versions using semantic versioning.
   230→// Returns true if current < latest.
   231→func isOutdated(current, latest string) bool {
   232→	// Ensure versions have "v" prefix for semver package
   233→	if !strings.HasPrefix(current, "v") {
   234→		current = "v" + current
   235→	}
   236→	if !strings.HasPrefix(latest, "v") {
   237→		latest = "v" + latest
   238→	}
   239→
   240→	// semver.Compare returns -1 if current < latest
   241→	return semver.Compare(current, latest) < 0
   242→}
   243→
   244→// updateCommand returns the appropriate update instruction based on how the binary was installed.
   245→func updateCommand() string {
   246→	execPath, err := os.Executable()
   247→	if err != nil {
   248→		return "curl -fsSL https://dl.entire.io/install.sh | bash"
   249→	}
   250→
   251→	// Resolve symlinks to find the real path (Homebrew symlinks from bin/ to Cellar/)
   252→	realPath, err := filepath.EvalSymlinks(execPath)
   253→	if err != nil {
   254→		realPath = execPath
   255→	}
   256→
   257→	if strings.Contains(realPath, "/Cellar/") || strings.Contains(realPath, "/homebrew/") {
   258→		return "brew upgrade entire"
   259→	}
   260→
   261→	return "curl -fsSL https://dl.entire.io/install.sh | bash"
   262→}
   263→
   264→// printNotification prints the version update notification to the user.
   265→func printNotification(cmd *cobra.Command, current, latest string) {
   266→	msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun '%s' to update.\n",
   267→		latest, current, updateCommand())
   268→	fmt.Fprint(cmd.OutOrStdout(), msg)
   269→}
