   131→	if err != nil {
   132→		return err
   133→	}
   134→
   135→	// Marshal to JSON
   136→	data, err := json.MarshalIndent(cache, "", "  ")
   137→	if err != nil {
   138→		return fmt.Errorf("marshaling cache: %w", err)
