   229→// isOutdated compares current and latest versions using semantic versioning.
   230→// Returns true if current < latest.
   231→func isOutdated(current, latest string) bool {
   232→	// Ensure versions have "v" prefix for semver package
   233→	if !strings.HasPrefix(current, "v") {
   234→		current = "v" + current
   235→	}
   236→	if !strings.HasPrefix(latest, "v") {
   237→		latest = "v" + latest
   238→	}
   239→
   240→	// semver.Compare returns -1 if current < latest
   241→	return semver.Compare(current, latest) < 0
   242→}
