   244→// updateCommand returns the appropriate update instruction based on how the binary was installed.
   245→func updateCommand() string {
   246→	execPath, err := os.Executable()
   247→	if err != nil {
   248→		return "curl -fsSL https://dl.entire.io/install.sh | bash"
   249→	}
   250→
   251→	// Resolve symlinks to find the real path (Homebrew symlinks from bin/ to Cellar/)
   252→	realPath, err := filepath.EvalSymlinks(execPath)
   253→	if err != nil {
   254→		realPath = execPath
   255→	}
   256→
   257→	if strings.Contains(realPath, "/Cellar/") || strings.Contains(realPath, "/homebrew/") {
   258→		return "brew upgrade entire"
   259→	}
   260→
   261→	return "curl -fsSL https://dl.entire.io/install.sh | bash"
   262→}
